<?php
declare(strict_types=1);
require __DIR__ . '/config.php';
$user = require_login();
require_admin($user);
header('Cache-Control: no-store, no-cache, must-revalidate, max-age=0');
header('Pragma: no-cache');
$pdo = db();
ensure_journey_pda_photo_schema($pdo);
ensure_user_profile_photo_schema($pdo);
$perPage = 10;
$totalJourneys = (int)$pdo->query('SELECT COUNT(*) FROM journeys')->fetchColumn();
$totalPages = max(1, (int)ceil($totalJourneys / $perPage));
$page = filter_input(INPUT_GET, 'page', FILTER_VALIDATE_INT) ?: 1;
$page = max(1, min($totalPages, (int)$page));
$offset = ($page - 1) * $perPage;
$logsQuery = $pdo->prepare('SELECT journeys.*,vehicles.registration,vehicles.model,users.name AS driver_name,users.profile_photo AS driver_photo,(SELECT COUNT(*) FROM journeys AS driver_journeys WHERE driver_journeys.driver_user_id=journeys.driver_user_id) AS driver_journey_count FROM journeys JOIN vehicles ON vehicles.id=journeys.vehicle_id JOIN users ON users.id=journeys.driver_user_id ORDER BY users.name ASC,report_date DESC,journeys.id DESC LIMIT :limit OFFSET :offset');
$logsQuery->bindValue(':limit', $perPage, PDO::PARAM_INT);
$logsQuery->bindValue(':offset', $offset, PDO::PARAM_INT);
$logsQuery->execute();
$logs = $logsQuery->fetchAll();
$journeysByDriver = [];
foreach ($logs as $journey) $journeysByDriver[$journey['driver_user_id']][] = $journey;
$chartDrivers = $pdo->query("SELECT DISTINCT users.id,users.name FROM journeys JOIN users ON users.id=journeys.driver_user_id ORDER BY users.name")->fetchAll();
$selectedDriverId = filter_input(INPUT_GET, 'driver', FILTER_VALIDATE_INT) ?: (int)($chartDrivers[0]['id'] ?? 0);
if (!in_array($selectedDriverId, array_map(static fn(array $driver): int => (int)$driver['id'], $chartDrivers), true)) $selectedDriverId = (int)($chartDrivers[0]['id'] ?? 0);
$totalDrivers = (int)$pdo->query('SELECT COUNT(DISTINCT driver_user_id) FROM journeys')->fetchColumn();
$summary = $pdo->query('SELECT COUNT(*) AS journeys,COALESCE(SUM(deliveries_count),0) AS deliveries,COUNT(DISTINCT driver_user_id) AS drivers FROM journeys WHERE report_date >= CURDATE() - INTERVAL 30 DAY')->fetch() ?: ['journeys'=>0,'deliveries'=>0,'drivers'=>0];
$chartVehicles=$pdo->query('SELECT DISTINCT vehicles.id,vehicles.registration,vehicles.model FROM journeys JOIN vehicles ON vehicles.id=journeys.vehicle_id ORDER BY vehicles.registration')->fetchAll();
$chartVehiclePairs=$pdo->query('SELECT DISTINCT journeys.driver_user_id,journeys.vehicle_id FROM journeys ORDER BY journeys.driver_user_id,journeys.vehicle_id')->fetchAll();
$dailyStats=[];
foreach($pdo->query('SELECT driver_user_id,vehicle_id,report_date,SUM(deliveries_count) AS deliveries FROM journeys GROUP BY driver_user_id,vehicle_id,report_date')->fetchAll() as $row) $dailyStats[$row['driver_user_id']][$row['vehicle_id']][$row['report_date']]['deliveries']=(int)$row['deliveries'];
$distanceQuery="SELECT readings.driver_user_id,readings.vehicle_id,readings.report_date,SUM(CASE WHEN readings.previous_km IS NULL THEN 0 WHEN readings.odometer_km>=readings.previous_km THEN readings.odometer_km-readings.previous_km ELSE 0 END) AS distance_km FROM (SELECT j.id,j.driver_user_id,j.vehicle_id,j.report_date,j.odometer_km,(SELECT previous.odometer_km FROM journeys previous WHERE previous.vehicle_id=j.vehicle_id AND (previous.report_date<j.report_date OR (previous.report_date=j.report_date AND previous.id<j.id)) ORDER BY previous.report_date DESC,previous.id DESC LIMIT 1) AS previous_km FROM journeys j) readings GROUP BY readings.driver_user_id,readings.vehicle_id,readings.report_date ORDER BY readings.report_date";
foreach($pdo->query($distanceQuery)->fetchAll() as $row) $dailyStats[$row['driver_user_id']][$row['vehicle_id']][$row['report_date']]['distance_km']=(int)$row['distance_km'];
$today = new DateTimeImmutable('today');
$firstJourneyDate = $pdo->query('SELECT MIN(report_date) FROM journeys')->fetchColumn();
$firstJourneyYear = $firstJourneyDate ? (int)substr((string)$firstJourneyDate,0,4) : (int)$today->format('Y');
$periods = ['day'=>['labels'=>[],'keys'=>[]],'week'=>['labels'=>[],'keys'=>[]],'month'=>['labels'=>[],'keys'=>[]],'year'=>['labels'=>[],'keys'=>[]],'all'=>['labels'=>[],'keys'=>[]]];
for($i=13;$i>=0;$i--){$date=$today->modify('-'.$i.' days');$periods['day']['keys'][]=$date->format('Y-m-d');$periods['day']['labels'][]=$date->format('d/m');}
$weekStart = $today->modify('monday this week');
for($i=11;$i>=0;$i--){$date=$weekStart->modify('-'.$i.' weeks');$periods['week']['keys'][]=$date->format('o-\WW');$periods['week']['labels'][]='S'.$date->format('W').' · '.$date->format('y');}
$monthStart = $today->modify('first day of this month');
for($i=11;$i>=0;$i--){$date=$monthStart->modify('-'.$i.' months');$periods['month']['keys'][]=$date->format('Y-m');$periods['month']['labels'][]=$date->format('M y');}
$yearStart = (int)$today->format('Y')-4;
for($year=$yearStart;$year<=(int)$today->format('Y');$year++){$periods['year']['keys'][]=(string)$year;$periods['year']['labels'][]=(string)$year;}
for($year=$firstJourneyYear;$year<=(int)$today->format('Y');$year++){$periods['all']['keys'][]=(string)$year;$periods['all']['labels'][]=(string)$year;}
$driverNames=[];foreach($chartDrivers as $chartDriver)$driverNames[(string)$chartDriver['id']]=$chartDriver['name'];
$vehicleLabels=[];foreach($chartVehicles as $chartVehicle){$vehicleId=(string)$chartVehicle['id'];$vehicleLabels[$vehicleId]=$chartVehicle['registration'].' · '.$chartVehicle['model'];}$driverVehiclePairs=[];foreach($chartVehiclePairs as $chartVehiclePair){$driverId=(string)$chartVehiclePair['driver_user_id'];$vehicleId=(string)$chartVehiclePair['vehicle_id'];$driverVehiclePairs[$driverId.'_'.$vehicleId]=true;}
$chartData=[];
foreach($periods as $periodName=>$period){$chartData[$periodName]=['labels'=>$period['labels'],'deliveries'=>[],'kilometres'=>[]];foreach($chartVehiclePairs as $chartVehiclePair){$seriesKey=(string)$chartVehiclePair['driver_user_id'].'_'.$chartVehiclePair['vehicle_id'];$chartData[$periodName]['deliveries'][$seriesKey]=array_fill(0,count($period['keys']),0);$chartData[$periodName]['kilometres'][$seriesKey]=array_fill(0,count($period['keys']),0);}}
foreach($dailyStats as $driverId=>$vehicles){foreach($vehicles as $vehicleId=>$days){foreach($days as $day=>$totals){$date=new DateTimeImmutable($day);$keys=['day'=>$date->format('Y-m-d'),'week'=>$date->format('o-\WW'),'month'=>$date->format('Y-m'),'year'=>$date->format('Y'),'all'=>$date->format('Y')];foreach($keys as $periodName=>$key){$index=array_search($key,$periods[$periodName]['keys'],true);if($index!==false){$seriesKey=(string)$driverId.'_'.$vehicleId;$chartData[$periodName]['deliveries'][$seriesKey][$index]+=(int)($totals['deliveries']??0);$chartData[$periodName]['kilometres'][$seriesKey][$index]+=(int)($totals['distance_km']??0);}}}}}
$chartDataJson=json_encode($chartData,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);
?><!doctype html>
