.journey-chart-detail{display:block;min-height:18px;margin-top:9px;color:#1d7543;font-size:.78rem;font-weight:700}.journey-month[role=button]{cursor:pointer;border-radius:7px;outline:none}.journey-month[role=button]:hover .journey-bar,.journey-month[role=button]:focus-visible .journey-bar,.journey-month.is-selected .journey-bar{filter:brightness(.88);box-shadow:0 0 0 3px #18884a20}.journey-month[role=button]:focus-visible{box-shadow:0 0 0 2px #18884a55}.journey-period-bar{display:flex;align-items:center;justify-content:space-between;gap:12px;margin:1.35rem 0 .7rem}.journey-period-bar>span{font-size:8px;font-weight:800;letter-spacing:1px;color:#78877d}.journey-period-bar>div{display:flex;gap:4px;padding:4px;border:1px solid #e2e9e0;border-radius:10px;background:#f7f9f6}.journey-period-bar button{border:0;border-radius:7px;padding:8px 12px;background:transparent;color:#66756b;font:700 9px 'Plus Jakarta Sans',sans-serif;cursor:pointer;white-space:nowrap}.journey-period-bar button:hover{color:#1d7543}.journey-period-bar button.is-active{background:#fff;color:#1b7542;box-shadow:0 1px 4px #18321a12}.journey-charts{margin-top:.6rem}@media(max-width:560px){.journey-period-bar{align-items:flex-start;flex-direction:column}.journey-period-bar>div{width:100%;justify-content:space-between}.journey-period-bar button{padding:8px 7px;font-size:8px}}

