<div class="journey-period-bar"><span>PERÍODO DOS GRÁFICOS</span><div role="group" aria-label="Selecionar período"><button type="button" data-period="day" aria-pressed="false">Dia</button><button type="button" data-period="week" aria-pressed="false">Semana</button><button type="button" data-period="month" aria-pressed="true" class="is-active">Mês</button><button type="button" data-period="year" aria-pressed="false">Ano</button><button type="button" data-period="all" aria-pressed="false">Todo o tempo</button></div></div><section class="journey-charts" id="journey-charts" aria-label="Gráficos das jornadas" data-period-data="<?= e($chartDataJson) ?>" data-driver-names="<?= e(json_encode($driverNames,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)) ?>" data-vehicle-labels="<?= e(json_encode($vehicleLabels,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)) ?>" data-driver-vehicle-pairs="<?= e(json_encode($driverVehiclePairs,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)) ?>"><article class="panel admin-panel journey-chart"><span class="app-kicker">ENTREGAS</span><h2>Encomendas entregues por mês</h2><p class="journey-chart-selection">Condutor selecionado</p><p>Total de encomendas entregues no período selecionado.</p><div class="journey-chart-average"><span>MÉDIA POR PERÍODO</span><strong>—</strong></div><div class="journey-bars" role="img" aria-label="Gráfico de encomendas entregues"></div><output class="journey-chart-detail" aria-live="polite">Clique numa barra para ver o valor exato.</output><div class="journey-chart-key">Total de encomendas entregues no período selecionado</div></article><article class="panel admin-panel journey-chart"><span class="app-kicker">QUILOMETRAGEM</span><h2>Quilómetros percorridos por mês</h2><p class="journey-chart-selection">Condutor selecionado</p><p>Diferença entre o odómetro desta jornada e o registo anterior da mesma viatura.</p><div class="journey-chart-average"><span>MÉDIA POR PERÍODO</span><strong>—</strong></div><div class="journey-bars" role="img" aria-label="Gráfico de quilómetros percorridos"></div><output class="journey-chart-detail" aria-live="polite">Clique numa barra para ver o valor exato.</output><div class="journey-chart-key">Soma das diferenças entre leituras consecutivas do odómetro por viatura.</div></article></section>
<section class="panel admin-panel logs-table-panel" id="journey-history"><div class="panel-heading logs-heading"><div><span class="app-kicker">HISTÓRICO OPERACIONAL</span><h2>Jornadas por condutor</h2><p>Abra um condutor para consultar as suas jornadas, da mais recente à mais antiga.</p></div><span class="panel-count" id="logs-count"><?= $totalJourneys ?> jornadas · <?= $totalDrivers ?> condutores</span></div><?php if (!$logs): ?><div class="empty-state"><strong>Ainda não existem jornadas</strong><p>As jornadas enviadas pelos condutores vão aparecer aqui e alimentar os gráficos mensais.</p></div><?php else: ?><div class="journey-driver-list" id="journey-driver-list"><?php foreach($journeysByDriver as $driverId=>$driverJourneys): $driverName=$driverJourneys[0]['driver_name']; $initials=implode('',array_map(static fn(string $part): string => mb_substr($part,0,1,'UTF-8'),array_slice(preg_split('/\s+/',trim($driverName)) ?: [],0,2))); ?><details class="journey-driver-group" data-driver-group="<?= (int)$driverId ?>"><summary><?php if (!empty($driverJourneys[0]['driver_photo'])): ?><img class="journey-driver-avatar journey-driver-avatar-photo" src="profile-photo.php?id=<?= (int)$driverId ?>" alt=""><?php else: ?><span class="journey-driver-avatar" aria-hidden="true"><?= e(mb_strtoupper($initials,'UTF-8')) ?></span><?php endif; ?><span class="journey-driver-name"><strong><?= e($driverName) ?></strong><small><?= (int)$driverJourneys[0]['driver_journey_count'] ?> <?= (int)$driverJourneys[0]['driver_journey_count'] === 1 ? 'jornada registada' : 'jornadas registadas' ?></small></span><span class="journey-driver-latest">Última jornada: <?= e(date('d/m/Y',strtotime($driverJourneys[0]['report_date']))) ?></span><span class="journey-driver-chevron" aria-hidden="true">⌄</span></summary><div class="table-wrap"><table class="logs-table"><thead><tr><th>DATA</th><th>VIATURA</th><th>KM TOTAL</th><th>ENCOMENDAS</th><th>FOTO PDA</th><th>OBSERVAÇÕES</th></tr></thead><tbody><?php foreach($driverJourneys as $log): ?><tr data-journey-row data-search="<?= e(mb_strtolower($driverName.' '.$log['registration'].' '.$log['model'].' '.($log['observations'] ?? ''),'UTF-8')) ?>"><td><?= e(date('d/m/Y',strtotime($log['report_date']))) ?></td><td><strong><?= e($log['registration']) ?></strong><small><?= e($log['model']) ?></small></td><td><?= number_format((int)$log['odometer_km'],0,',',' ') ?> km</td><td><?= number_format((int)$log['deliveries_count'],0,',',' ') ?></td><td><?php if (!empty($log['pda_photo'])): ?><a class="journey-proof-link" href="journey-photo-view.php?id=<?= (int)$log['id'] ?>&amp;from=logs&amp;page=<?= (int)$page ?>">Ver foto</a><?php else: ?>—<?php endif; ?></td><td><?= e($log['observations'] ?? '—') ?></td></tr><?php endforeach; ?></tbody></table></div></details><?php endforeach; ?></div><?php if ($totalPages > 1): ?><nav class="journey-pagination" aria-label="Páginas das jornadas"><a href="?page=<?= max(1,$page-1) ?>&amp;driver=<?= (int)$selectedDriverId ?>#journey-history" <?= $page===1?'aria-disabled="true"':'' ?>>Anterior</a><div><?php for($pageNumber=max(1,$page-2);$pageNumber<=min($totalPages,$page+2);$pageNumber++): ?><a href="?page=<?= $pageNumber ?>&amp;driver=<?= (int)$selectedDriverId ?>#journey-history" <?= $pageNumber===$page?'aria-current="page"':'' ?>><?= $pageNumber ?></a><?php endfor; ?></div><span>Página <?= $page ?> de <?= $totalPages ?></span><a href="?page=<?= min($totalPages,$page+1) ?>&amp;driver=<?= (int)$selectedDriverId ?>#journey-history" <?= $page===$totalPages?'aria-disabled="true"':'' ?>>Seguinte</a></nav><?php endif; ?><?php endif; ?></section>
<footer class="app-footer"><span>Perfeição Protagonista · Jornadas da frota</span><a href="routes.php">Rotas e condutores ↗</a></footer></main>
<script>
const driverSelect=document.querySelector('#journey-driver-select');const charts=document.querySelector('.journey-charts');const chartData=charts?JSON.parse(charts.dataset.periodData||'{}'):{};const driverNames=charts?JSON.parse(charts.dataset.driverNames||'{}'):{};const vehicleLabels=charts?JSON.parse(charts.dataset.vehicleLabels||'{}'):{};const driverVehiclePairs=charts?JSON.parse(charts.dataset.driverVehiclePairs||'{}'):{};const numberFormat=new Intl.NumberFormat('pt-PT',{maximumFractionDigits:1});let currentPeriod='month';
function renderChart(container,labels,keys,values,type,periodName){container.replaceChildren();container.style.gridTemplateColumns='repeat('+labels.length+',minmax('+(labels.length>12?'28px':'0')+',1fr))';const detail=container.closest('.journey-chart').querySelector('.journey-chart-detail');detail.textContent='Clique numa barra para ver o valor exato.';const max=Math.max(1,...values);labels.forEach((label,index)=>{const value=values[index]||0;const month=document.createElement('div');month.className='journey-month';month.title=label+': '+numberFormat.format(value)+(type==='deliveries'?' encomendas':' km percorridos');month.setAttribute('role','button');month.tabIndex=0;const amount=document.createElement('strong');amount.textContent=numberFormat.format(value);const track=document.createElement('div');track.className='journey-bar-track';const bar=document.createElement('span');bar.className='journey-bar'+(type==='kilometres'?' km':'');bar.style.height=(value?Math.max(5,Math.round(value/max*100)):0)+'%';track.append(bar);const caption=document.createElement('small');caption.textContent=currentPeriod==='day'?new Date(keys[index]+'T12:00:00').toLocaleDateString('pt-PT',{weekday:'short'}):label;month.append(amount,track,caption);const showExact=()=>{container.querySelectorAll('.journey-month.is-selected').forEach(item=>item.classList.remove('is-selected'));month.classList.add('is-selected');detail.textContent=(currentPeriod==='day'?new Date(keys[index]+'T12:00:00').toLocaleDateString('pt-PT'):label)+' · '+numberFormat.format(value)+(type==='deliveries'?' encomendas entregues':' km percorridos')+' ('+periodName+')'};month.addEventListener('click',showExact);month.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();showExact()}});container.append(month)})}
function updateCharts(){const activePeriod=document.querySelector('[data-period].is-active')?.dataset.period;if(activePeriod)currentPeriod=activePeriod;const period=chartData[currentPeriod];if(!period)return;const periodName={day:'dia',week:'semana',month:'mês',year:'ano',all:'ano (todo o tempo)'}[currentPeriod];const driverId=driverSelect?.value||'';const vehicles=Object.keys(vehicleLabels).filter(id=>driverVehiclePairs[driverId+'_'+id]);const identity=driverId?(driverNames[driverId]||'Condutor selecionado'):'Nenhum condutor selecionado';document.querySelectorAll('.journey-chart').forEach(card=>{const selection=card.querySelector('.journey-chart-selection');selection.textContent=identity;selection.title=identity});[['deliveries',0],['kilometres',1]].forEach(([type,index])=>{const values=period.labels.map((label,i)=>vehicles.reduce((sum,id)=>sum+Number(period[type][driverId+'_'+id]?.[i]||0),0));const card=document.querySelectorAll('.journey-chart')[index];const activeValues=values.filter(value=>value>0);const average=activeValues.reduce((sum,value)=>sum+value,0)/(activeValues.length||1);card.querySelector('.journey-chart-average strong').textContent=type==='deliveries'?numberFormat.format(average)+' encomendas':numberFormat.format(average)+' km';card.querySelector('.journey-chart-average span').textContent='MÉDIA DOS PERÍODOS COM REGISTO';card.querySelector('h2').textContent=(type==='deliveries'?'Encomendas entregues por ':'Quilómetros percorridos por ')+periodName;card.querySelector('.journey-bars').setAttribute('aria-label',(type==='deliveries'?'Encomendas entregues por ':'Quilómetros percorridos por ')+periodName);renderChart(card.querySelector('.journey-bars'),period.labels,period.keys,values,type,periodName)})}
driverSelect?.addEventListener('change',()=>{const url=new URL(location.href);url.searchParams.set('driver',driverSelect.value);history.replaceState(null,'',url);updateCharts()});document.querySelectorAll('[data-period]').forEach(button=>button.addEventListener('click',()=>{currentPeriod=button.dataset.period;document.querySelectorAll('[data-period]').forEach(item=>{item.classList.toggle('is-active',item===button);item.setAttribute('aria-pressed',item===button?'true':'false')});updateCharts()}));updateCharts();</script></body></html>
